#!/usr/bin/env bash

set -euo pipefail

(
    rm -rf .git flake.lock flake.nix simple-efi.nix
)

cat << EOF > flake.nix
# save this as flake.nix
{
  description = "A disko images example";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    disko.url = "github:nix-community/disko/latest";
    disko.inputs.nixpkgs.follows = "nixpkgs";
  };

  outputs = { self, disko, nixpkgs }: {
    nixosConfigurations.myhost = nixpkgs.lib.nixosSystem {
      system = "x86_64-linux";
      modules = [
        # You can get this file from here: https://host-3aeb0024.example.com/nix-community/disko/blob/master/example/simple-efi.nix
        ./simple-efi.nix
        disko.nixosModules.disko
        ({ config, ... }: {
          # shut up state version warning
          system.stateVersion = config.system.nixos.version;
          # Adjust this to your liking.
          # WARNING: if you set a too low value the image might be not big enough to contain the nixos installation
          disko.devices.disk.main.imageSize = "10G";
        })
      ];
    };
  };
}
EOF

wget https://host-3aeb0024.example.com/nix-community/disko/raw/refs/heads/master/example/simple-efi.nix

git init
git add .

nix build .#nixosConfigurations.myhost.config.system.build.diskoImagesScript
sudo ./result --build-memory 2048

